  d.status = ROUTER_DISPATCH_LIFECYCLE_V2.FAILED;
  d.updatedAt = now;
  if (!d.settledAt) d.settledAt = now;
  if (reason) d.metadata.failReason = String(reason);
  return { ...d, metadata: { ...d.metadata } };
