}
export function getArgovRoutingStuckMsV2() {
  return _argovStuckMs;
}
export function _resetStateAgentRouterGovV2() {
  _argovPsV2.clear();
  _argovJsV2.clear();
  _argovMaxActive = 8;
  _argovMaxPending = 20;
