  if (!j) throw new Error(`argov routing ${id} not found`);
  _argovCheckJ(j.status, ARGOV_ROUTING_LIFECYCLE_V2.FAILED);
  const now = Date.now();
  j.status = ARGOV_ROUTING_LIFECYCLE_V2.FAILED;
  j.updatedAt = now;
