      j.status === ARGOV_ROUTING_LIFECYCLE_V2.ROUTING_RUN &&
      j.startedAt != null &&
      t - j.startedAt >= _argovStuckMs
    ) {
      j.status = ARGOV_ROUTING_LIFECYCLE_V2.FAILED;
      j.updatedAt = t;
      if (!j.settledAt) j.settledAt = t;
