describe("AgentRouter default-deny dispatch", () => {
  it.each(["round-robin", "primary", "by-type", "parallel-all"])(
    "rejects ungoverned %s dispatch before starting a backend",
    async (strategy) => {
      const cli = makeCliBackend(BACKEND_TYPE.CLAUDE);
