/**
 * image-input — multimodal (vision) input for `cc agent`.
 *
 * cc's internal message format is OpenAI-shaped, so the internal multimodal
 * representation is OpenAI's: a user message whose `content` is an array of
 * `{type:"text"}` / `{type:"image_url", image_url:{url:"data:<media>;base64,..."}}`
 * parts. The OpenAI-compatible providers (openai/volcengine/deepseek/…) accept
 * that verbatim, so their branch needs no conversion. ollama and anthropic use
 * different shapes — `toOllamaMessages` and `imageUrlBlockToAnthropic` convert.
 *
 * All functions are pure (except `resolveImages`, which reads files via the
 * injectable `_deps.fs`).
 */

import fs from "fs";
import path from "path";
import os from "os";
import {
  MAX_INPUT_IMAGES,
  MAX_INPUT_IMAGE_BYTES,
  readBoundedImage,
} from "./image-file-boundary.js";

/**
 * Candidate on-disk forms for a path token typed in a prompt, so a path copied
 * from a Git-Bash / MSYS shell still resolves on Windows. Order = most-literal
 * first: the raw token, then the MSYS drive form (`/c/Users/…` → `C:/Users/…`),
 * then `~`/`~/…` home expansion. The caller attaches the first that exists.
 */
function localPathCandidates(raw) {
  const cands = [raw];
  const msys = /^\/([a-zA-Z])\/(.*)$/.exec(raw); // /c/Users/x → C:/Users/x
  if (msys) cands.push(`${msys[1].toUpperCase()}:/${msys[2]}`);
  if (raw === "~" || raw.startsWith("~/") || raw.startsWith("~\\")) {
    cands.push(path.join(os.homedir(), raw.slice(1)));
  }
  return cands;
}

/**
 * Convert a local `file://` URI to a filesystem path so a dragged/pasted image
 * (IDEs often hand back `file:///C:/Users/…/a.png`) is recognized like a bare
 * path. Strips the scheme, percent-decodes, and drops the leading slash before
 * a Windows drive (`/C:/…` → `C:/…`). Returns null for non-file URIs.
 */
function fileUriToPath(uri) {
  if (!/^file:\/\//i.test(uri)) return null;
  let p = uri.replace(/^file:\/\//i, "");
  try {
    p = decodeURIComponent(p);
  } catch {
    /* leave as-is if it isn't valid percent-encoding */
  }
  if (/^\/[a-zA-Z]:/.test(p)) p = p.slice(1); // /C:/Users/x → C:/Users/x
  return p;
}

const EXT_MEDIA = {
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".webp": "image/webp",
};

/**
 * Read `--image <path>` values into `[{ mediaType, data(base64) }]`.
 * Throws on an unsupported extension so a typo fails loudly instead of sending
 * a broken request.
 */
export function resolveImages(paths, deps = {}) {
  const _fs = deps.fs || fs;
  if (!Array.isArray(paths) || paths.length === 0) return [];
  if (paths.length > MAX_INPUT_IMAGES)
    throw new Error(`Attach at most ${MAX_INPUT_IMAGES} images per message`);
  let remainingBytes = MAX_INPUT_IMAGE_BYTES;
  return paths.map((p, index) => {
    const ext = path.extname(String(p)).toLowerCase();
    const mediaType = EXT_MEDIA[ext];
    if (!mediaType) {
      throw new Error(
        `Unsupported image type "${ext || p}" — use png/jpg/jpeg/gif/webp.`,
      );
    }
    try {
      const data = readBoundedImage(p, mediaType, remainingBytes, _fs);
      remainingBytes -= data.length;
      return { mediaType, data: data.toString("base64") };
    } catch (error) {
      throw new Error(`Image ${index + 1}: ${error.message}`, { cause: error });
    }
  });
}

/**
 * Claude-Code-style auto-detection: find local image-file paths mentioned in a
 * prompt so the turn can attach them as vision input. A token is treated as an
 * image only when (a) its extension is one we support and (b) the file actually
 * exists on disk — so prose like "I edited a.png" attaches only when a.png is
 * really there, and a typo'd/remote path stays as plain text. Matched path
 * tokens are stripped from the returned text ("describe ./a.png" → "describe" +
 * an attachment); an all-path message leaves empty text, which the caller turns
 * into an image-only turn. URLs / data: URIs are never auto-attached (local
 * files only). Pure except for the existence check (inject `deps.existsSync`).
 *
 * @param {string} text
 * @param {object} deps  { existsSync }
 * @returns {{ images: string[], text: string }}
 */
export function detectImagePaths(text, deps = {}) {
  const existsSync = deps.existsSync || fs.existsSync;
  if (typeof text !== "string" || !text.trim()) {
    return { images: [], text: typeof text === "string" ? text : "" };
  }
  const exts = Object.keys(EXT_MEDIA)
    .map((e) => e.slice(1))
    .join("|"); // png|jpg|jpeg|gif|webp
  // Quoted ("…"/'…') paths first (may contain spaces), then bare
  // whitespace-delimited tokens ending in a supported image extension.
  const re = new RegExp(
    `"([^"]+?\\.(?:${exts}))"|'([^']+?\\.(?:${exts}))'|(\\S+?\\.(?:${exts}))(?=$|[\\s)\\]'",])`,
    "gi",
  );
  const images = [];
  const seen = new Set();
  const ranges = [];
  let m;
  while ((m = re.exec(text)) !== null) {
    const raw = m[1] || m[2] || m[3];
    if (!raw) continue;
    // A local `file://` URI (common from drag/drop in IDEs) → a path token;
    // any other scheme (http/https/ftp/data…) is never auto-attached.
    let token = raw;
    if (/^file:\/\//i.test(raw)) {
      token = fileUriToPath(raw) || raw;
    } else if (/^[a-z][a-z0-9+.-]*:\/\//i.test(raw) || /^data:/i.test(raw)) {
      continue;
    }
    // Resolve to the first on-disk form (handles Git-Bash `/c/…` + `~`). The
    // RESOLVED path is what gets attached/read; the RAW token is stripped from
    // the text.
    let resolved = null;
    for (const cand of localPathCandidates(token)) {
      try {
        if (existsSync(cand)) {
          resolved = cand;
          break;
        }
      } catch {
        /* unreadable candidate — try the next form */
      }
    }
    if (!resolved) continue;
    if (!seen.has(resolved)) {
      seen.add(resolved);
      images.push(resolved);
    }
    ranges.push([m.index, m.index + m[0].length]);
  }
  if (!images.length) return { images: [], text };
  let out = text;
  for (let i = ranges.length - 1; i >= 0; i--) {
    out = out.slice(0, ranges[i][0]) + out.slice(ranges[i][1]);
  }
  out = out.replace(/ {2,}/g, " ").trim();
  return { images, text: out };
}

/**
 * Compose a REPL/interactive turn from raw typed text: auto-detect local image
 * paths, build the user-message content, and (on an image turn) the per-turn
 * vision-LLM override. Pure orchestration over detectImagePaths/resolveImages/
 * buildUserContent/resolveVisionLlm so the interactive wiring is unit-testable
 * (the REPL itself forces a terminal and can't be driven headlessly).
 *
 * @param {string} text     the user's typed message
 * @param {object} llm      { provider, baseUrl, apiKey, visionModel } current LLM
 * @param {object} deps     { existsSync, fs } injected for tests
 * @returns {{ content, images: string[], visionLlm: object|null, text: string }}
 *   content is a plain string when no image is detected, else a multimodal
 *   array; visionLlm is the per-turn provider/model/baseUrl/apiKey override
 *   (null when there are no images); text is the path-stripped prompt.
 */
export function prepareVisionTurn(text, llm = {}, deps = {}) {
  const detected = detectImagePaths(text, deps);
  if (!detected.images.length) {
    return { content: text, images: [], visionLlm: null, text };
  }
  const finalText = detected.text || "Please look at the attached image(s).";
  const resolved = resolveImages(detected.images, deps); // throws on bad ext
  return {
    content: buildUserContent(finalText, resolved),
    images: detected.images,
    visionLlm: resolveVisionLlm({ hasImage: true, flags: {}, llm }),
    text: finalText,
  };
}

/**
 * Build a user-message `content`: the plain string when there are no images,
 * else an OpenAI-style multimodal array (the internal representation).
 */
export function buildUserContent(text, images) {
  if (!Array.isArray(images) || images.length === 0) return text;
  const parts = [];
  if (text) parts.push({ type: "text", text });
  for (const img of images) {
    parts.push({
      type: "image_url",
      image_url: { url: `data:${img.mediaType};base64,${img.data}` },
    });
  }
  return parts;
}

/** Parse a `data:<media>;base64,<data>` URL into `{ mediaType, data }` or null. */
export function parseDataUrl(url) {
  const m = /^data:([^;,]+);base64,(.*)$/s.exec(String(url || ""));
  return m ? { mediaType: m[1], data: m[2] } : null;
}

/** True when a message carries any image_url part (i.e. needs provider conversion). */
export function hasImageContent(messages) {
  return (messages || []).some(
    (m) =>
      Array.isArray(m?.content) &&
      m.content.some((p) => p?.type === "image_url"),
  );
}

/**
 * Convert OpenAI-shaped multimodal messages for the ollama `/api/chat` body:
 * ollama wants `{ content: "<text>", images: ["<base64>", …] }` (bare base64,
 * no `data:` prefix). Non-multimodal messages pass through untouched.
 */
export function toOllamaMessages(messages) {
  return (messages || []).map((m) => {
    if (!m || !Array.isArray(m.content)) return m;
    let text = "";
    const images = [];
    for (const part of m.content) {
      if (part?.type === "text") {
        text += (text ? "\n" : "") + (part.text || "");
      } else if (part?.type === "image_url") {
        const parsed = parseDataUrl(part.image_url?.url);
        if (parsed) images.push(parsed.data);
        else if (part.image_url?.url) images.push(part.image_url.url);
      }
    }
    const out = { ...m, content: text };
    if (images.length) out.images = images;
    return out;
  });
}

/**
 * Convert one OpenAI `image_url` content block into an Anthropic `image` block,
 * or null when it isn't an image_url block / has no usable data URL.
 */
export function imageUrlBlockToAnthropic(block) {
  if (!block || block.type !== "image_url") return null;
  const parsed = parseDataUrl(block.image_url?.url);
  if (!parsed) return null;
  return {
    type: "image",
    source: { type: "base64", media_type: parsed.mediaType, data: parsed.data },
  };
}

/**
 * Default vision model when none is configured — Volcengine Ark
 * Doubao-Seed-2.0-lite (id `doubao-seed-2-0-lite-260215`, dated YYMMDD =
 * 2026-02-15), a natively multimodal model (text/image/video; 2.0 has no
 * separate "-vision-" SKU). Override via --vision-model or config.llm.visionModel
 * to pin a different snapshot.
 */
export const DEFAULT_VISION_MODEL = "doubao-seed-2-0-lite-260215";

/**
 * Resolve the effective LLM config for a run. When an image is attached, default
 * the provider/model/baseUrl/apiKey to the configured vision LLM so
 * `cc agent --image foo.png` works without extra flags — using `llm.visionModel`
 * (a separate, configurable vision model) and falling back to DEFAULT_VISION_MODEL.
 * Explicit flags always win; with no image, behaviour is unchanged (vision config
 * is ignored). `--vision-model` overrides the configured/default vision model.
 *
 * @param {object} p
 * @param {boolean} p.hasImage  true when the run carries an attached image
 * @param {object}  p.flags     { provider, model, baseUrl, apiKey, visionModel }
 * @param {object}  p.llm       config.llm ({ provider, model, baseUrl, apiKey, visionModel })
 * @returns {{provider, model, baseUrl, apiKey}}
 */
export function resolveVisionLlm({ hasImage, flags = {}, llm = {} } = {}) {
  // No image → no vision override; the caller falls back to its normal LLM
  // config (`visionLlm.x || options.x`).
  if (!hasImage) {
    return {
      provider: undefined,
      model: undefined,
      baseUrl: undefined,
      apiKey: undefined,
    };
  }
  const visionModel =
    flags.visionModel || llm.visionModel || DEFAULT_VISION_MODEL;
  // `flags.model` must be the EXPLICIT `--model` (not a settings/default), so an
  // attached image uses the vision model unless the user deliberately picked one.
  return {
    provider: flags.provider || llm.provider,
    model: flags.model || visionModel,
    baseUrl: flags.baseUrl || llm.baseUrl,
    apiKey: flags.apiKey || llm.apiKey,
  };
}

/**
 * Multimodal (vision) input helpers for `cc agent --image`. Pure-shape unit
 * tests; the live path is exercised against a vision-capable provider (e.g.
 * volcengine doubao) in an E2E.
 */
import { describe, it, expect } from "vitest";
import { PNG_BYTES, imageFsFixture } from "../helpers/image-file-fixtures.js";
import {
  resolveImages,
  buildUserContent,
  parseDataUrl,
  hasImageContent,
  toOllamaMessages,
  imageUrlBlockToAnthropic,
  resolveVisionLlm,
  detectImagePaths,
  prepareVisionTurn,
  DEFAULT_VISION_MODEL,
} from "../../src/lib/image-input.js";

const fakeFs = imageFsFixture();

describe("resolveImages", () => {
  it("returns [] for no paths", () => {
    expect(resolveImages(undefined)).toEqual([]);
    expect(resolveImages([])).toEqual([]);
  });

  it("reads files → {mediaType, base64 data} with media type from extension", () => {
    const out = resolveImages(["a.png", "b.JPG", "c.webp"], { fs: fakeFs });
    expect(out.map((x) => x.mediaType)).toEqual([
      "image/png",
      "image/jpeg",
      "image/webp",
    ]);
    expect(out[0].data).toBe(PNG_BYTES.toString("base64"));
  });

  it("throws on an unsupported extension", () => {
    expect(() => resolveImages(["doc.pdf"], { fs: fakeFs })).toThrow(
      /Unsupported image type/,
    );
  });
});

describe("buildUserContent", () => {
  it("returns the plain string when there are no images", () => {
    expect(buildUserContent("hello", [])).toBe("hello");
    expect(buildUserContent("hello", undefined)).toBe("hello");
  });

  it("builds an OpenAI multimodal array (text first, then image_url)", () => {
    const out = buildUserContent("what is this", [
      { mediaType: "image/png", data: "AAAA" },
    ]);
    expect(out).toEqual([
      { type: "text", text: "what is this" },
      {
        type: "image_url",
        image_url: { url: "data:image/png;base64,AAAA" },
      },
    ]);
  });
});

describe("parseDataUrl", () => {
  it("parses a valid data URL", () => {
    expect(parseDataUrl("data:image/jpeg;base64,ZZ==")).toEqual({
      mediaType: "image/jpeg",
      data: "ZZ==",
    });
  });
  it("returns null on a non-data URL", () => {
    expect(parseDataUrl("https://x/y.png")).toBeNull();
    expect(parseDataUrl("")).toBeNull();
  });
});

describe("hasImageContent", () => {
  it("detects image_url parts", () => {
    expect(
      hasImageContent([
        {
          role: "user",
          content: [
            {
              type: "image_url",
              image_url: { url: "data:image/png;base64,A" },
            },
          ],
        },
      ]),
    ).toBe(true);
    expect(hasImageContent([{ role: "user", content: "plain" }])).toBe(false);
  });
});

describe("toOllamaMessages", () => {
  it("converts multimodal content to {content, images[base64]}", () => {
    const out = toOllamaMessages([
      {
        role: "user",
        content: [
          { type: "text", text: "look" },
          {
            type: "image_url",
            image_url: { url: "data:image/png;base64,AAAA" },
          },
        ],
      },
    ]);
    expect(out[0]).toEqual({
      role: "user",
      content: "look",
      images: ["AAAA"],
    });
  });
  it("passes string-content messages through untouched", () => {
    const msgs = [{ role: "assistant", content: "hi", tool_calls: [] }];
    expect(toOllamaMessages(msgs)).toEqual(msgs);
  });
});

describe("imageUrlBlockToAnthropic", () => {
  it("converts an image_url block to an Anthropic image block", () => {
    expect(
      imageUrlBlockToAnthropic({
        type: "image_url",
        image_url: { url: "data:image/png;base64,AAAA" },
      }),
    ).toEqual({
      type: "image",
      source: { type: "base64", media_type: "image/png", data: "AAAA" },
    });
  });
  it("returns null for non-image blocks", () => {
    expect(imageUrlBlockToAnthropic({ type: "text", text: "x" })).toBeNull();
  });
});

describe("resolveVisionLlm", () => {
  const llm = {
    provider: "volcengine",
    model: "doubao-text",
    baseUrl: "https://ark/api",
    apiKey: "K",
    visionModel: "doubao-1-5-vision-pro-32k-250115",
  };

  it("with no image: ignores vision config (provider/model undefined unless flagged)", () => {
    expect(resolveVisionLlm({ hasImage: false, flags: {}, llm })).toEqual({
      provider: undefined,
      model: undefined,
      baseUrl: undefined,
      apiKey: undefined,
    });
  });

  it("with an image: switches to configured vision provider/model/baseUrl/apiKey", () => {
    expect(resolveVisionLlm({ hasImage: true, flags: {}, llm })).toEqual({
      provider: "volcengine",
      model: "doubao-1-5-vision-pro-32k-250115",
      baseUrl: "https://ark/api",
      apiKey: "K",
    });
  });

  it("explicit flags always win over vision config", () => {
    const out = resolveVisionLlm({
      hasImage: true,
      flags: {
        provider: "openai",
        model: "gpt-4o",
        baseUrl: "u",
        apiKey: "k2",
      },
      llm,
    });
    expect(out).toEqual({
      provider: "openai",
      model: "gpt-4o",
      baseUrl: "u",
      apiKey: "k2",
    });
  });

  it("--vision-model overrides the configured vision model", () => {
    expect(
      resolveVisionLlm({
        hasImage: true,
        flags: { visionModel: "my-vlm" },
        llm,
      }).model,
    ).toBe("my-vlm");
  });

  it("falls back to DEFAULT_VISION_MODEL when none configured", () => {
    expect(
      resolveVisionLlm({
        hasImage: true,
        flags: {},
        llm: { provider: "volcengine" },
      }).model,
    ).toBe(DEFAULT_VISION_MODEL);
  });
});

describe("detectImagePaths (Claude-Code-style path auto-detect)", () => {
  // existsSync stub: only these paths "exist".
  const mk = (existing) => ({
    existsSync: (p) => existing.includes(p),
  });

  it("attaches an existing local image path and strips it from the text", () => {
    const r = detectImagePaths(
      "describe ./shot.png please",
      mk(["./shot.png"]),
    );
    expect(r.images).toEqual(["./shot.png"]);
    expect(r.text).toBe("describe please");
  });

  it("handles a bare Windows path and an all-path message", () => {
    const win = String.raw`C:\tmp\a.png`;
    const r = detectImagePaths(win, mk([win]));
    expect(r.images).toEqual([win]);
    expect(r.text).toBe(""); // image-only → caller synthesizes a prompt
  });

  it("supports quoted paths with spaces + multiple images, deduped", () => {
    const spaced = String.raw`C:\my pics\a.png`;
    const r = detectImagePaths(
      `compare "${spaced}" and b.jpg and a.png again "${spaced}"`,
      mk([spaced, "b.jpg", "a.png"]),
    );
    expect(r.images).toEqual([spaced, "b.jpg", "a.png"]);
  });

  it("resolves a Git-Bash/MSYS drive path (/c/Users/… → C:/Users/…)", () => {
    // Only the Windows form exists on disk; the typed token is the /c/… form.
    const r = detectImagePaths(
      "描述 /c/Users/me/pics/a.png",
      mk(["C:/Users/me/pics/a.png"]),
    );
    expect(r.images).toEqual(["C:/Users/me/pics/a.png"]); // attaches resolved form
    expect(r.text).toBe("描述"); // raw token stripped
  });

  it("resolves a local file:// URI (IDE drag/drop) incl. %20 and /C: prefix", () => {
    const r = detectImagePaths(
      "describe file:///C:/Users/me/a.png now",
      mk(["C:/Users/me/a.png"]),
    );
    expect(r.images).toEqual(["C:/Users/me/a.png"]);
    expect(r.text).toBe("describe now");
    // percent-encoded space in a file:// URI is decoded before existence check
    const r2 = detectImagePaths(
      "see file:///C:/my%20pics/b.jpg",
      mk(["C:/my pics/b.jpg"]),
    );
    expect(r2.images).toEqual(["C:/my pics/b.jpg"]);
  });

  it("ignores non-existent paths, unsupported extensions, and URLs", () => {
    expect(detectImagePaths("see missing.png", mk([])).images).toEqual([]);
    expect(
      detectImagePaths("a report.pdf here", mk(["report.pdf"])).images,
    ).toEqual([]);
    expect(
      detectImagePaths("https://x.com/p.png", mk(["https://x.com/p.png"]))
        .images,
    ).toEqual([]);
  });

  it("returns text unchanged when nothing matches; tolerates non-strings", () => {
    expect(detectImagePaths("just words", mk([]))).toEqual({
      images: [],
      text: "just words",
    });
    expect(detectImagePaths("", mk([]))).toEqual({ images: [], text: "" });
    expect(detectImagePaths(null, mk([]))).toEqual({ images: [], text: "" });
  });
});

describe("prepareVisionTurn (REPL interactive composition)", () => {
  const deps = (existing) => ({
    existsSync: (p) => existing.includes(p),
    fs: imageFsFixture(),
  });
  const llm = {
    provider: "volcengine",
    baseUrl: "https://ark/api",
    apiKey: "K",
    visionModel: "doubao-vlm",
  };

  it("no image path → plain text content, no vision override", () => {
    const r = prepareVisionTurn("just a question", llm, deps([]));
    expect(r.content).toBe("just a question");
    expect(r.images).toEqual([]);
    expect(r.visionLlm).toBeNull();
  });

  it("image path → multimodal content + vision LLM override (model switched)", () => {
    const r = prepareVisionTurn("describe a.png now", llm, deps(["a.png"]));
    expect(r.images).toEqual(["a.png"]);
    expect(Array.isArray(r.content)).toBe(true);
    expect(r.content[0]).toEqual({ type: "text", text: "describe now" });
    expect(r.content[1].type).toBe("image_url");
    // same provider/baseUrl/apiKey, model switched to the configured vision model
    expect(r.visionLlm).toEqual({
      provider: "volcengine",
      model: "doubao-vlm",
      baseUrl: "https://ark/api",
      apiKey: "K",
    });
  });

  it("path-only message → synthesized instruction + attachment", () => {
    const r = prepareVisionTurn("a.png", llm, deps(["a.png"]));
    expect(r.content[0].text).toMatch(/attached image/);
    expect(r.visionLlm.model).toBe("doubao-vlm");
  });

  it("falls back to the default vision model when none configured", () => {
    const r = prepareVisionTurn(
      "see a.png",
      { provider: "volcengine" },
      deps(["a.png"]),
    );
    expect(r.visionLlm.model).toBe(DEFAULT_VISION_MODEL);
  });
});

import fs from "node:fs";

// CLI keeps its existing eight-image allowance; IDE composers admit four.
export const MAX_INPUT_IMAGES = 8;
export const MAX_INPUT_IMAGE_BYTES = 20 * 1024 * 1024;
export const MAX_INPUT_IMAGE_PIXELS = 40_000_000;
const MAX_HEADER_BYTES = 1024 * 1024;

/** Header admission only, not a full codec decode or animation-frame budget. */
export function inspectImageHeader(data) {
  const ascii = (start, end) => data.toString("ascii", start, end);
  if (
    data.length >= 33 &&
    data
      .subarray(0, 8)
      .equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])) &&
    data.readUInt32BE(8) === 13 &&
    ascii(12, 16) === "IHDR"
  ) {
    return {
      mediaType: "image/png",
      width: data.readUInt32BE(16),
      height: data.readUInt32BE(20),
    };
  }
  if (data.length >= 13 && ["GIF87a", "GIF89a"].includes(ascii(0, 6))) {
    return {
      mediaType: "image/gif",
      width: data.readUInt16LE(6),
      height: data.readUInt16LE(8),
    };
  }
  if (data.length >= 30 && ascii(0, 4) === "RIFF" && ascii(8, 12) === "WEBP") {
    const kind = ascii(12, 16);
    if (kind === "VP8X")
      return {
        mediaType: "image/webp",
        width: data.readUIntLE(24, 3) + 1,
        height: data.readUIntLE(27, 3) + 1,
      };
    if (
      kind === "VP8 " &&
      data[23] === 157 &&
      data[24] === 1 &&
      data[25] === 42
    )
      return {
        mediaType: "image/webp",
        width: data.readUInt16LE(26) & 16383,
        height: data.readUInt16LE(28) & 16383,
      };
    if (kind === "VP8L" && data[20] === 47) {
      const bits = data.readUInt32LE(21);
      return {
        mediaType: "image/webp",
        width: (bits & 16383) + 1,
        height: ((bits >>> 14) & 16383) + 1,
      };
    }
  }
  if (data.length >= 4 && data[0] === 255 && data[1] === 216) {
    let offset = 2;
    while (offset + 4 <= data.length) {
      if (data[offset++] !== 255) break;
      while (data[offset] === 255) offset++;
      const marker = data[offset++];
      if (marker === 217 || marker === 218) break;
      if (marker === 1 || (marker >= 208 && marker <= 215)) continue;
      if (offset + 2 > data.length) break;
      const length = data.readUInt16BE(offset);
      if (length < 2 || offset + length > data.length) break;
      if (
        [
          192, 193, 194, 195, 197, 198, 199, 201, 202, 203, 205, 206, 207,
        ].includes(marker) &&
        length >= 8
      ) {
        return {
          mediaType: "image/jpeg",
          width: data.readUInt16BE(offset + 5),
          height: data.readUInt16BE(offset + 3),
        };
      }
      offset += length;
    }
  }
  throw new Error(
    "Unsupported or malformed image header (dimensions must occur within the first 1 MiB)",
  );
}

function readAtMost(io, fd, data) {
  let offset = 0;
  while (offset < data.length) {
    const count = io.readSync(fd, data, offset, data.length - offset, offset);
    if (count === 0) break;
    offset += count;
  }
  return offset;
}

/** Pin one regular-file descriptor and cap allocation/read even if it grows. */
export function readBoundedImage(
  file,
  expectedMediaType,
  remainingBytes,
  io = fs,
) {
  // O_NONBLOCK avoids hanging while opening a FIFO on POSIX. fstat then
  // rejects all non-regular files; Windows has no O_NONBLOCK flag here.
  const fd = io.openSync(
    file,
    fs.constants.O_RDONLY | (fs.constants.O_NONBLOCK || 0),
  );
  try {
    const before = io.fstatSync(fd);
    if (!before.isFile()) throw new Error("Image input must be a regular file");
    if (
      !Number.isSafeInteger(before.size) ||
      before.size <= 0 ||
      before.size > MAX_INPUT_IMAGE_BYTES
    )
      throw new Error("Image must contain 1 byte to 20 MiB");
    if (before.size > remainingBytes)
      throw new Error("Total image attachments exceed 20 MiB per message");
    const header = Buffer.alloc(Math.min(before.size, MAX_HEADER_BYTES));
    const headerSize = readAtMost(io, fd, header);
    const info = inspectImageHeader(header.subarray(0, headerSize));
    if (info.mediaType !== expectedMediaType)
      throw new Error("Image extension does not match its file header");
    if (
      !info.width ||
      !info.height ||
      info.width * info.height > MAX_INPUT_IMAGE_PIXELS
    )
      throw new Error(
        "Image dimensions must be positive and at most 40 megapixels",
      );
    const data = Buffer.alloc(before.size + 1);
    const count = readAtMost(io, fd, data);
    const after = io.fstatSync(fd);
    if (
      count !== before.size ||
      after.size !== before.size ||
      after.mtimeMs !== before.mtimeMs ||
      after.ctimeMs !== before.ctimeMs ||
      !data.subarray(0, headerSize).equals(header.subarray(0, headerSize))
    )
      throw new Error("Image changed while being read; select it again");
    return data.subarray(0, count);
  } finally {
    io.closeSync(fd);
  }
}

import fs from "node:fs";

export const PNG_BYTES = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==",
  "base64",
);

// Header fixtures exercise admission, not complete codec decoding.
export function imageHeader(format) {
  if (format === "png") return Buffer.from(PNG_BYTES);
  if (format === "jpeg")
    return Buffer.from([
      255, 216, 255, 192, 0, 11, 8, 0, 2, 0, 3, 1, 1, 17, 0, 255, 217,
    ]);
  if (format === "gif") return Buffer.from("47494638396103000200000000", "hex");
  const bytes = Buffer.alloc(30);
  bytes.write("RIFF");
  bytes.writeUInt32LE(22, 4);
  bytes.write("WEBPVP8X", 8);
  bytes.writeUInt32LE(10, 16);
  bytes.writeUIntLE(2, 24, 3);
  bytes.writeUIntLE(1, 27, 3);
  return bytes;
}

export function imageFsFixture() {
  return {
    openSync(file) {
      return imageHeader(
        /\.jpe?g$/i.test(file)
          ? "jpeg"
          : /\.webp$/i.test(file)
            ? "webp"
            : /\.gif$/i.test(file)
              ? "gif"
              : "png",
      );
    },
    fstatSync(data) {
      return { size: data.length, mtimeMs: 1, ctimeMs: 1, isFile: () => true };
    },
    readSync(data, target, offset, length, position) {
      return data.copy(target, offset, position, position + length);
    },
    closeSync() {},
    constants: fs.constants,
  };
}

